script:
frappe.listview_settings['DCU'] = {
    onload: function(listview) {
        listview.page.add_inner_button('Refresh', function() {
            frappe.show_alert({message: 'Fetching DCU status...', indicator: 'blue'});
            frappe.call({
                method: "upande_hydrax.upande_hydrax.tasks.sync_dcu_status",
                callback: function(r) {
                    frappe.show_alert({message: 'DCU status updated', indicator: 'green'});
                    listview.refresh();
                },
                error: function(r) {
                    frappe.show_alert({message: 'Sync failed — check Error Log', indicator: 'red'});
                }
            });
        });
    }
};

frappe.listview_settings['Token Record'] = {
    onload: function(listview) {
        listview.page.add_inner_button('Get Record', function() {
            frappe.show_alert({message: 'Fetching token records...', indicator: 'blue'});
            frappe.call({
                method: "upande_hydrax.upande_hydrax.tasks.sync_all_token_records",
                callback: function(r) {
                    frappe.show_alert({message: 'Token records updated', indicator: 'green'});
                    listview.refresh();
                },
                error: function(r) {
                    frappe.show_alert({message: 'Sync failed — check Error Log', indicator: 'red'});
                }
            });
        });
    }
};
